char *freqAlphabets(char *s) {
  int n = strlen(s);
  char *res = (char *)malloc(n + 1);
  int p = 0;
  for (int i = 0; i < n; i++) {
    if (i + 2 < n && s[i + 2] == '#') {
      int num = (s[i] - '0') * 10 + (s[i + 1] - '0');
      res[p++] = 'a' + num - 1;
      i += 2;
    } else {
      res[p++] = 'a' + (s[i] - '0') - 1;
    }
  }
  res[p] = '\0';
  return res;
}

func freqAlphabets(s string) string {
	n := len(s)
	res := []byte{}
	for i := 0; i < n; i++ {
		if i+2 < n && s[i+2] == '#' {
			num := int(s[i]-'0')*10 + int(s[i+1]-'0')
			res = append(res, byte('a'+num-1))
			i += 2
		} else {
			res = append(res, byte('a'+int(s[i]-'0')-1))
		}
	}
	return string(res)
}

class Solution {
  public String freqAlphabets(String s) {
    StringBuilder sb = new StringBuilder();
    int n = s.length();
    for (int i = 0; i < n; i++) {
      if (i + 2 < n && s.charAt(i + 2) == '#') {
        int num = (s.charAt(i) - '0') * 10 + (s.charAt(i + 1) - '0');
        sb.append((char) ('a' + num - 1));
        i += 2;
      } else {
        sb.append((char) ('a' + (s.charAt(i) - '0') - 1));
      }
    }
    return sb.toString();
  }
}

class Solution:
    def freqAlphabets(self, s: str) -> str:
        res = []
        i = 0
        n = len(s)
        while i < n:
            if i + 2 < n and s[i + 2] == "#":
                res.append(chr(ord("a") + int(s[i:i + 2]) - 1))
                i += 3
            else:
                res.append(chr(ord("a") + int(s[i]) - 1))
                i += 1
        return "".join(res)

impl Solution {
  pub fn freq_alphabets(s: String) -> String {
    let b = s.as_bytes();
    let n = b.len();
    let mut res = String::new();
    let mut i = 0;
    while i < n {
      if i + 2 < n && b[i + 2] == b'#' {
        let num = (b[i] - b'0') as i32 * 10 + (b[i + 1] - b'0') as i32;
        res.push((b'a' + num as u8 - 1) as char);
        i += 3;
      } else {
        res.push((b'a' + (b[i] - b'0') - 1) as char);
        i += 1;
      }
    }
    res
  }
}

const freqAlphabets = (s: string): string => {
  let res = '';
  const n = s.length;
  for (let i = 0; i < n; i++) {
    if (i + 2 < n && s[i + 2] === '#') {
      const num = (s.charCodeAt(i) - 48) * 10 + (s.charCodeAt(i + 1) - 48);
      res += String.fromCharCode(97 + num - 1);
      i += 2;
    } else {
      res += String.fromCharCode(97 + (s.charCodeAt(i) - 48) - 1);
    }
  }
  return res;
};

class Solution {
public:
  string freqAlphabets(string s) {
    unordered_map<string, char> mp;
    for (int i = 1; i <= 9; i++)
      mp[to_string(i)] = 'a' + i - 1;

    for (int i = 10; i <= 26; i++)
      mp[to_string(i) + '#'] = 'j' + i - 10;

    string result = "";
    for (int i = 0; i < s.size(); i++) {
      if (i + 2 < s.size()) {
        auto t = s.substr(i, 3);
        if (mp.count(t)) {
          result += mp[t];
          i += 2;
          continue;
        }
      }
      result += mp[s.substr(i, 1)];
    }
    return result;
  }
};
